### <mark>冒泡排序</mark>

```c++
#include <bits/stdc++.h>
using namespace std;
int a[n];
//这里省略对数组a的输入
for(int i = 0;i<n-1;i++){//n个数，则进行n-1次交换
    for(int j = 0;j<n-1-i;j++){//每一次的交换（因为已经完成了i次交换）
        if(a[j]>a[j+1]){//从小到大排序
            swap(a[j],a[j+1]);//交换
        }
    }
}
```

