## <mark>二分+最大加权平均</mark>

![最大加权平均](image/例题/最大加权平均.png)

注意，严格来说，整体最大加权平均不等于单个最大性价比中挑选最优的



```c++
#include<bits/stdc++.h>
using namespace std;
const int maxn = 10005;
int n,k;
vector<pair<int,int>> cv(maxn);
double arr[maxn];
bool check(double x){
    for(int i = 0;i<n;i++){
        arr[i] = cv[i].second-x*cv[i].first;
    }
    sort(arr,arr+n,greater<double>());
    double sum = 0;
    for(int i = 0;i<k;i++){
        sum+=arr[i];
    }
    return sum>=0;
}
int main(){
    int t;
    cin>>t;
    while(t--){
        cin>>n>>k;
        for(int i = 0;i<n;i++){
            cin>>cv[i].first>>cv[i].second;
        }
        double l = 0,r = 1e7,ans = 0;
        for(int i = 0;i<75;i++){
            double mid = (l+r)/2;
            if(check(mid)){
                ans = mid;
                l = mid;//double型，小心不要写成"l = mid+1"
            }else{
                r = mid;
            }
        }
        cout<<int(ans)<<endl;
    }
    return 0;
}
```


