## <mark>2的幂次方表示</mark>

知识点：主要还是`递归`吧 有点麻烦

题目：在ZJNU的Oline Judge上吧

解法：

```c++
#include <bits/stdc++.h>
using namespace std;
string solve(int n){
    if(n==1)return "2(0)";//雷霆递归（哭
    if(n==2)return "2";
    string result = "";
    for(int power = 14;power>-1;power--){
        int two_power = 1;
        for(int j = 0;j<power;j++){
            two_power = two_power*2;
        }
        if(n>=two_power){
            if(result!=""){
                result += "+";
            }
            if(power==1){
                result += "2";
            }else if(power==0){
                result += "2(0)";
            }else{
                result += "2("+solve(power)+")";
            }
            n -= two_power;
        }
    }
    return result;
}
int main(){
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        cout<<solve(n)<<endl;
    }
    return 0;
}
```

