## <mark>二分+差分(借教室)</mark>

![借教室](image/例题/zjnuoj借教室.png)

策略：利用二分查找第一个不能满足的订单

利用实时的差分判断当前是否符合

```c++
#include<bits/stdc++.h>
using namespace std;
#define ll long long
struct borrow{
    ll d;
    ll s;
    ll t;
};
ll n,m;
vector<ll> rooms;//初始每天的空余房间
vector<borrow> orders;//所有订单
bool check(int k){//判断前k份订单能否满足
    vector<ll> diff(n+2,0);//差分数组
    for(int i = 1;i<=k;i++){
        diff[orders[i].s]+=orders[i].d;
        diff[orders[i].t+1]-=orders[i].d;
    }
    ll need = 0;
    for(int i = 1;i<=n;i++){
    //在只考虑前k个订单的前提下，遍历n天，看看是否全部能够满足。若不能，就说明不能满足前K个订单
        need+=diff[i];
        if(need>rooms[i]){
            return false;
        }
    }
    return true;
}
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin>>n>>m;
    rooms.resize(n+1);
    for(ll i = 1;i<=n;i++){
        cin>>rooms[i];
    }
    orders.resize(m+1);
    for(ll i = 1;i<=m;i++){
        cin>>orders[i].d>>orders[i].s>>orders[i].t;
    }
    ll l = 1;ll r = m;ll ans = -1;
    while(l<=r){
        ll mid = (l+r)/2;
        if(!check(mid)){
            ans = mid;
            r = mid-1;//继续查找第一个不满足的订单
        }else{
            l = mid+1;
        }
    }
    if(ans==-1){
        cout<<0<<endl;
    }else{
        cout<<-1<<endl;
        cout<<ans<<endl;
    }
    return 0;
}
```

